DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.financeiro_movimentacoes) THEN RAISE EXCEPTION 'Existem movimentacoes legadas: identificar a conta antes de migrar.'; END IF; END $$;
ALTER TABLE public.financeiro_movimentacoes ADD COLUMN status text NOT NULL DEFAULT 'realizado' CHECK(status IN ('previsto','realizado','cancelado')), ADD COLUMN data_vencimento date, ADD COLUMN data_pagamento date, ADD COLUMN conta_id uuid REFERENCES public.financeiro_contas(id), ADD COLUMN categoria_id uuid REFERENCES public.financeiro_categorias(id), ADD COLUMN projeto_id uuid REFERENCES public.projetos(id), ADD COLUMN cliente_id uuid REFERENCES public.clientes(id), ADD COLUMN colaborador_id uuid REFERENCES public.colaboradores(id), ADD COLUMN area_id uuid REFERENCES public.areas(id), ADD COLUMN parcela_id uuid REFERENCES public.financeiro_parcelas(id), ADD COLUMN forma_pagamento text CHECK(forma_pagamento IN ('pix','boleto','transferencia','cartao','dinheiro','debito_automatico','outro')), ADD COLUMN documento text, ADD COLUMN comprovante_path text, ADD COLUMN transferencia_id uuid, ADD COLUMN recorrencia_id uuid, ADD COLUMN origem text NOT NULL DEFAULT 'manual' CHECK(origem IN ('manual','conversa','importacao','extrato')), ADD COLUMN id_externo text, ADD COLUMN revisar boolean NOT NULL DEFAULT false, ADD COLUMN observacoes text, ADD COLUMN criado_por uuid, ADD COLUMN atualizado_por uuid;
UPDATE public.financeiro_movimentacoes SET data_pagamento=data_movimentacao WHERE status='realizado';
ALTER TABLE public.financeiro_movimentacoes ALTER COLUMN status SET DEFAULT 'previsto';
ALTER TABLE public.financeiro_parcelas ADD COLUMN movimentacao_id uuid REFERENCES public.financeiro_movimentacoes(id);
CREATE UNIQUE INDEX financeiro_parcela_movimentacao_unique ON public.financeiro_parcelas(movimentacao_id) WHERE movimentacao_id IS NOT NULL;
CREATE UNIQUE INDEX financeiro_origem_externo_unique ON public.financeiro_movimentacoes(origem,id_externo) WHERE id_externo IS NOT NULL;
CREATE UNIQUE INDEX financeiro_estoque_unique ON public.financeiro_movimentacoes(estoque_movimentacao_id) WHERE estoque_movimentacao_id IS NOT NULL;
CREATE INDEX fin1_data_pagamento ON public.financeiro_movimentacoes(data_pagamento);
CREATE INDEX fin1_status_vencimento ON public.financeiro_movimentacoes(status,data_vencimento);
CREATE INDEX fin1_conta ON public.financeiro_movimentacoes(conta_id);
CREATE INDEX fin1_categoria ON public.financeiro_movimentacoes(categoria_id);
CREATE INDEX fin1_projeto ON public.financeiro_movimentacoes(projeto_id);
CREATE INDEX fin1_cliente ON public.financeiro_movimentacoes(cliente_id);
CREATE INDEX fin1_colaborador ON public.financeiro_movimentacoes(colaborador_id);
CREATE INDEX fin1_area ON public.financeiro_movimentacoes(area_id);
CREATE INDEX fin1_parcela ON public.financeiro_movimentacoes(parcela_id);
CREATE INDEX fin1_recorrencia ON public.financeiro_movimentacoes(recorrencia_id,data_vencimento);
CREATE INDEX fin1_transferencia ON public.financeiro_movimentacoes(transferencia_id);
CREATE INDEX fin1_revisar ON public.financeiro_movimentacoes(revisar) WHERE revisar=true;
CREATE INDEX fin1_competencia ON public.financeiro_movimentacoes(data_movimentacao);
COMMENT ON COLUMN public.financeiro_movimentacoes.categoria IS 'DEPRECATED: categoria_id e a categoria canonica do Caixa; texto preservado para compatibilidade com estoque.';
COMMENT ON COLUMN public.financeiro_movimentacoes.valor IS 'FIN-1: valor em reais; uma unica fonte da verdade do pagamento. Parcela.valor e plano, valor_recebido e espelho derivado.';
CREATE OR REPLACE FUNCTION public.fin1_authorized(p_totals boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.has_any_role(auth.uid(),CASE WHEN p_totals THEN ARRAY['admin','diretor']::public.user_role[] ELSE ARRAY['admin','administrativo','gestor','diretor']::public.user_role[] END) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND ativo IS TRUE) AND NOT EXISTS(SELECT 1 FROM public.user_access_security WHERE user_id=auth.uid() AND must_change_password IS TRUE) $$;
REVOKE ALL ON FUNCTION public.fin1_authorized(boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fin1_authorized(boolean) TO authenticated,service_role;
DROP POLICY "Admins can delete financial movements" ON public.financeiro_movimentacoes;
DROP POLICY "Finance users can insert financial movements" ON public.financeiro_movimentacoes;
DROP POLICY "Finance users can update financial movements" ON public.financeiro_movimentacoes;
DROP POLICY "Finance users can view financial movements" ON public.financeiro_movimentacoes;
REVOKE ALL ON public.financeiro_movimentacoes,public.financeiro_parcelas,public.financeiro_contas,public.financeiro_categorias FROM anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.financeiro_movimentacoes TO authenticated; GRANT ALL ON public.financeiro_movimentacoes TO service_role;
CREATE POLICY fin1_mov_read ON public.financeiro_movimentacoes FOR SELECT TO authenticated USING((SELECT public.fin1_authorized(false)));
CREATE POLICY fin1_mov_insert ON public.financeiro_movimentacoes FOR INSERT TO authenticated WITH CHECK((SELECT public.fin1_authorized(false)));
CREATE POLICY fin1_mov_update ON public.financeiro_movimentacoes FOR UPDATE TO authenticated USING((SELECT public.fin1_authorized(false))) WITH CHECK((SELECT public.fin1_authorized(false)));
CREATE POLICY fin1_mov_delete ON public.financeiro_movimentacoes FOR DELETE TO authenticated USING((SELECT public.fin1_authorized(false)) AND (SELECT public.has_role(auth.uid(),'admin')));
DROP POLICY "Admin e adm podem criar parcelas" ON public.financeiro_parcelas; DROP POLICY "Admin e adm podem editar parcelas" ON public.financeiro_parcelas; DROP POLICY "Admin e adm podem excluir parcelas" ON public.financeiro_parcelas; DROP POLICY "Admin e adm podem ver parcelas" ON public.financeiro_parcelas;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.financeiro_parcelas TO authenticated; GRANT ALL ON public.financeiro_parcelas TO service_role;
CREATE POLICY fin1_parcela_read ON public.financeiro_parcelas FOR SELECT TO authenticated USING((SELECT public.fin1_authorized(false)));
CREATE POLICY fin1_parcela_insert ON public.financeiro_parcelas FOR INSERT TO authenticated WITH CHECK((SELECT public.fin1_authorized(false)));
CREATE POLICY fin1_parcela_update ON public.financeiro_parcelas FOR UPDATE TO authenticated USING((SELECT public.fin1_authorized(false))) WITH CHECK((SELECT public.fin1_authorized(false)));
CREATE POLICY fin1_parcela_delete ON public.financeiro_parcelas FOR DELETE TO authenticated USING((SELECT public.fin1_authorized(false)) AND (SELECT public.has_role(auth.uid(),'admin')));
CREATE OR REPLACE FUNCTION public.fin1_validate_movement() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v_type text; BEGIN
 IF TG_OP='INSERT' AND NEW.estoque_movimentacao_id IS NOT NULL AND NEW.data_vencimento IS NULL AND NEW.data_pagamento IS NULL THEN RETURN NULL; END IF;
 IF NEW.valor<=0 THEN RAISE EXCEPTION 'Valor deve ser maior que zero.'; END IF;
 IF NEW.status='realizado' AND (NEW.data_pagamento IS NULL OR NEW.conta_id IS NULL) THEN RAISE EXCEPTION 'Realizado exige data de pagamento e conta.'; END IF;
 IF NEW.status='previsto' AND NEW.data_vencimento IS NULL THEN RAISE EXCEPTION 'Previsto exige vencimento.'; END IF;
 IF NEW.categoria_id IS NULL THEN SELECT id INTO NEW.categoria_id FROM public.financeiro_categorias WHERE nome='A classificar' AND tipo=NEW.tipo; NEW.revisar=true; END IF;
 SELECT tipo INTO v_type FROM public.financeiro_categorias WHERE id=NEW.categoria_id;
 IF v_type IS DISTINCT FROM NEW.tipo THEN RAISE EXCEPTION 'Categoria deve corresponder ao tipo de lancamento.'; END IF;
 IF NEW.status='cancelado' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) AND COALESCE(NULLIF(btrim(current_setting('fin1.motivo',true)),''),'')='' THEN RAISE EXCEPTION 'Motivo obrigatorio para cancelar.'; END IF;
 IF TG_OP='INSERT' THEN NEW.criado_por=auth.uid(); END IF; NEW.atualizado_por=auth.uid();
 RETURN NEW; END $$;
CREATE TRIGGER fin1_validate BEFORE INSERT OR UPDATE ON public.financeiro_movimentacoes FOR EACH ROW EXECUTE FUNCTION public.fin1_validate_movement();
CREATE OR REPLACE FUNCTION public.fin1_audit_movement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO public.audit_status_changes(entity_table,entity_id,status_anterior,status_novo,changed_by,changed_by_nome,metadata) VALUES('financeiro_movimentacoes',NEW.id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.status END,NEW.status,auth.uid(),(SELECT nome FROM public.profiles WHERE id=auth.uid()),jsonb_build_object('motivo',NULLIF(current_setting('fin1.motivo',true),''))); END IF;
 RETURN NEW; END $$;
CREATE TRIGGER fin1_audit AFTER INSERT OR UPDATE ON public.financeiro_movimentacoes FOR EACH ROW EXECUTE FUNCTION public.fin1_audit_movement();